public struct TectonicIconView: View {
    public let icon: TectonicIcon
    public var size: CGFloat = 16
    public var color: Color = .primary
    public var strokeWidth: CGFloat = 2

    public init(icon: TectonicIcon, size: CGFloat = 16, color: Color = .primary, strokeWidth: CGFloat = 2) {
        self.icon = icon
        self.size = size
        self.color = color
        self.strokeWidth = strokeWidth
    }

    public var body: some View {
        IconPolyline(paths: icon.polylines)
            .stroke(color, style: StrokeStyle(lineWidth: strokeWidth, lineCap: .round, lineJoin: .round))
            .frame(width: size, height: size)
            .accessibilityHidden(true)
    }
}

public struct IconPolyline: Shape {
    public let paths: [[CGPoint]]

    public init(paths: [[CGPoint]]) { self.paths = paths }

    public func path(in rect: CGRect) -> Path {
        var p = Path()
        let scale = min(rect.width / 24.0, rect.height / 24.0)
        let ox = rect.midX - 12 * scale
        let oy = rect.midY - 12 * scale
        for poly in paths {
            guard let first = poly.first else { continue }
            p.move(to: CGPoint(x: first.x * scale + ox, y: first.y * scale + oy))
            for pt in poly.dropFirst() {
                p.addLine(to: CGPoint(x: pt.x * scale + ox, y: pt.y * scale + oy))
            }
        }
        return p
    }
}

