    /// 解码为折线点序列（Float32 扁平数组，每折线以 -1 分隔）
    public var polylines: [[CGPoint]] {
        guard let raw = Data(base64Encoded: data) else { return [] }
        var floats: [Float] = []
        floats.reserveCapacity(raw.count / 4)
        raw.withUnsafeBytes { buf in
            for i in stride(from: 0, to: buf.count, by: 4) {
                let v = buf.loadUnaligned(fromByteOffset: i, as: Float.self)
                floats.append(v)
            }
        }
        var paths: [[CGPoint]] = []
        var cur: [CGPoint] = []
        var pendingX: Float? = nil
        for v in floats {
            if v < 0 {
                if !cur.isEmpty { paths.append(cur); cur = [] }
                pendingX = nil
            } else if let px = pendingX {
                cur.append(CGPoint(x: CGFloat(px), y: CGFloat(v)))
                pendingX = nil
            } else {
                pendingX = v
            }
        }
        if !cur.isEmpty { paths.append(cur) }
        return paths
    }
